-- Expanded Holistic House engaging battery v2 batch 1.
begin;
do $$
declare
  cfg jsonb;
  locale text;
  questions jsonb;
  item_ids jsonb;
  dimension_class text;
  direction text;
  timeframe text;
  definition jsonb;
  test_id uuid;
  v_content_hash text;
begin
  for cfg in select value from jsonb_array_elements($configs$[{"key":"hh-sleep-reset","titles":{"en":"Sleep Reset","ru":"Перезагрузка сна"},"axis":"resources","topics":["sleep","recovery","energy"],"categoryAffinities":["body","energy","other"],"testLength":"short","en":["My sleep has felt restorative lately.","I can wind down without staying mentally switched on for too long.","I wake with at least some usable energy.","My sleep schedule feels reasonably predictable.","I can notice what most disrupts my sleep.","I have at least one habit that helps my body prepare for rest."],"ru":["В последнее время сон ощущается восстанавливающим.","Я могу постепенно выключаться вечером, не оставаясь надолго мысленно включённым.","Я просыпаюсь хотя бы с некоторым запасом энергии.","Мой режим сна достаточно предсказуем.","Я замечаю, что сильнее всего нарушает мой сон.","У меня есть хотя бы одна привычка, которая помогает телу готовиться ко сну."],"ids":{"en":"2c74f251-17e9-571a-a319-27826b0768a4","ru":"09ab59c8-5d85-52b4-a2bd-0391a7864143"},"hashes":{"en":"sha256:5193ec0bdbdf251935899ea030280cdf68426645ca082749bcd7b5f682708d7a","ru":"sha256:e1cffb926fd75a12c8fac1963701a78aa23f5bed11ae176e423e9a377102ca89"},"negative":false},{"key":"hh-morning-battery","titles":{"en":"Morning Battery","ru":"Утренняя батарейка"},"axis":"state","topics":["energy","clarity","function"],"categoryAffinities":["energy","body","work-money"],"testLength":"short","en":["I wake with enough energy to begin the day.","My mind becomes clear within a reasonable time after waking.","I can start the day without immediately feeling behind.","My body feels ready to move.","I know what deserves my first attention.","My morning routine supports rather than drains me."],"ru":["Я просыпаюсь с достаточной энергией, чтобы начать день.","После пробуждения ясность приходит достаточно быстро.","Я могу начать день без ощущения, что уже опаздываю.","Тело готово двигаться.","Я понимаю, чему стоит уделить первое внимание.","Мой утренний ритм скорее поддерживает, чем истощает меня."],"ids":{"en":"3f485eb4-f05a-51f0-b728-b9ca682d0a33","ru":"fa11aa66-fc63-5686-828b-ac8e827fee43"},"hashes":{"en":"sha256:4dfb657aaed69210a0be7f76721cb50e01178e09a1a2bd9dab8f0b7d797010d1","ru":"sha256:e01adadc85dc59abfd9e25d14355723178df14388da2bc809fa4fbe495cb192f"},"negative":false},{"key":"hh-evening-landing","titles":{"en":"Evening Landing","ru":"Вечернее приземление"},"axis":"resources","topics":["recovery","sleep","stress"],"categoryAffinities":["energy","body","other"],"testLength":"short","en":["I can slow down at the end of the day.","I can mentally leave unfinished tasks until tomorrow.","My body gets a signal that work is over.","I have some time without demands before sleep.","I can reduce stimulation when I need to.","The evening helps me recover from the day."],"ru":["В конце дня я могу замедлиться.","Я могу мысленно оставить незаконченные дела до завтра.","Тело получает сигнал, что рабочая часть дня закончена.","Перед сном у меня есть время без требований.","Я могу уменьшить стимуляцию, когда это нужно.","Вечер помогает мне восстановиться после дня."],"ids":{"en":"45cc15bf-f82e-5479-b5a6-8e45a3438960","ru":"58eb1a64-0985-5639-b365-0d8385b98369"},"hashes":{"en":"sha256:bbaf4f43032f4017b108e5276116ef450b09bdd622f4fc8089a7cc071ec0e79b","ru":"sha256:644db3860a01429795fae337f84adac9f2b07e878568bc85fb4d18b08fb5ef0f"},"negative":false},{"key":"hh-decision-fog","titles":{"en":"Decision Fog","ru":"Туман решений"},"axis":"function","topics":["clarity","function","stress"],"categoryAffinities":["work-money","energy","other"],"testLength":"short","en":["Simple decisions feel harder than they should.","I postpone choices because there are too many options.","I keep reopening decisions I already made.","I worry about choosing the wrong option.","Small choices consume noticeable mental energy.","After deciding, it is hard to move on."],"ru":["Простые решения даются тяжелее, чем должны.","Я откладываю выбор, потому что вариантов слишком много.","Я снова возвращаюсь к уже принятым решениям.","Я переживаю, что выберу не тот вариант.","Небольшие решения заметно съедают умственную энергию.","После решения мне трудно переключиться дальше."],"ids":{"en":"cc932f6c-2d4b-59a8-a341-783d3bf75ca1","ru":"021971b1-742e-5aea-852d-a1af99e22883"},"hashes":{"en":"sha256:f88bd28da38cd8886591cd12809cb2c7562d6c89779ac2de3decb44d410833ee","ru":"sha256:4405f0d59da5fdb308b89bdec73aecafd5e8e2e9e3e8dcc1f30b4fcb40a3ebca"},"negative":true},{"key":"hh-start-button","titles":{"en":"Start Button","ru":"Кнопка старта"},"axis":"function","topics":["attention","function","motivation"],"categoryAffinities":["work-money","energy","other"],"testLength":"short","en":["I can begin a task before I feel completely ready.","I can make the first step small enough to start.","I know what the first concrete action is.","I can tolerate a task being imperfect at the beginning.","Once I start, momentum usually becomes easier.","I can start important tasks without waiting for pressure."],"ru":["Я могу начать задачу до того, как почувствую себя полностью готовым.","Я умею уменьшить первый шаг так, чтобы было легко начать.","Я понимаю, какое первое конкретное действие нужно сделать.","Я могу позволить началу быть несовершенным.","После старта движение обычно становится легче.","Я могу начинать важное без ожидания сильного давления."],"ids":{"en":"13ea3326-f27a-532a-87e9-9f43da3991ba","ru":"60aa2f17-6ea1-5f63-b7fc-603061e1aca1"},"hashes":{"en":"sha256:aed348ff231309765c159d722ab5d15fc9f7f977823468518fe660c1cbcb880d","ru":"sha256:17219139ea23f1e9749d12d9c601e52976f51abd2335b9dd46b2c305221c434b"},"negative":false},{"key":"hh-screen-saturation","titles":{"en":"Screen Saturation","ru":"Перегруз экраном"},"axis":"state","topics":["clarity","stress","sleep","attention"],"categoryAffinities":["energy","work-money","other"],"testLength":"short","en":["After a lot of screen time, my mind feels overloaded.","I switch between apps or tabs without a clear reason.","Notifications pull my attention more than I want.","It is hard to stop scrolling even when I am tired.","Screens make it harder for me to wind down.","After time offline, I notice some mental relief."],"ru":["После большого количества экранного времени мозг ощущается перегруженным.","Я переключаюсь между приложениями или вкладками без ясной причины.","Уведомления сильнее отвлекают меня, чем хотелось бы.","Мне трудно перестать листать, даже когда я устал.","Экраны мешают мне постепенно успокаиваться.","После времени без экрана я замечаю некоторое облегчение."],"ids":{"en":"5f4f8e9e-47d5-5831-bef2-fb1701d275dc","ru":"0af7c9ec-c349-5a54-84cc-3ca23b9d4b07"},"hashes":{"en":"sha256:66c0afe8731d6d5fba0971c8f47e3a743a30b9d3ae3007f94e23adb5f32083c5","ru":"sha256:9d083d4278979cd450fc6ba4746fe1c884fc5ba3a5c6a6b4f57b1257bca95d3a"},"negative":true},{"key":"hh-inner-critic","titles":{"en":"Inner Critic Volume","ru":"Громкость внутреннего критика"},"axis":"state","topics":["mood","self-support","stress"],"categoryAffinities":["emotions","other"],"testLength":"short","en":["I judge myself harshly for small mistakes.","My inner commentary is more demanding than supportive.","I replay what I should have done differently.","I compare myself with others in a way that lowers my mood.","It is hard to acknowledge what I did well.","When something goes wrong, I quickly make it about my worth."],"ru":["Я жёстко сужу себя за небольшие ошибки.","Мой внутренний комментарий чаще требовательный, чем поддерживающий.","Я снова прокручиваю, что должен был сделать иначе.","Я сравниваю себя с другими так, что настроение ухудшается.","Мне трудно признать то, что я сделал хорошо.","Когда что-то идёт не так, я быстро связываю это со своей ценностью."],"ids":{"en":"9b54d264-cb6d-5d05-ac8c-2fdf8c2d3b62","ru":"8d43e1df-fe02-57ee-bec4-802a4231877b"},"hashes":{"en":"sha256:66e2b7edff29397c40c2fdefe6f60dad6e8e2be91129f933479686825beb13a6","ru":"sha256:5dff350ee212107a45ee5b93e5e484b68bedd8150827dabc787d0f7749857bce"},"negative":true},{"key":"hh-inner-ally","titles":{"en":"Inner Ally","ru":"Внутренний союзник"},"axis":"resources","topics":["self-support","recovery","mood"],"categoryAffinities":["emotions","other"],"testLength":"short","en":["I can speak to myself with respect when I struggle.","I can separate a mistake from my worth as a person.","I can give myself time to recover.","I can notice effort, not only results.","I can ask what I need instead of only pushing harder.","I can support myself without pretending everything is fine."],"ru":["Когда мне трудно, я могу говорить с собой уважительно.","Я могу отделить ошибку от собственной ценности как человека.","Я могу дать себе время на восстановление.","Я замечаю усилия, а не только результат.","Я могу спросить себя, что мне нужно, вместо того чтобы только сильнее давить.","Я могу поддержать себя, не делая вид, что всё прекрасно."],"ids":{"en":"e74efb49-32ed-501c-9392-c0954627aebd","ru":"6a061a12-0cdc-5860-b237-e7478181b0e2"},"hashes":{"en":"sha256:8e2e407c809d82fd174acfb1101a21bf10e7e88fd34113376bc442f18f50ea40","ru":"sha256:f06c7bb77de517ae6e9aae991eae23151000178982308de852018f0898fd024e"},"negative":false},{"key":"hh-meaning-compass","titles":{"en":"Meaning Compass","ru":"Компас смысла"},"axis":"resources","topics":["meaning","motivation","resources"],"categoryAffinities":["other","work-money","emotions"],"testLength":"medium","en":["I know what currently feels meaningful to me.","My daily actions connect with something I care about.","I can name what I want more of in my life.","I can tell the difference between what matters to me and what is merely expected.","I have at least one direction I want to move toward.","Even during difficulty, I can see some reason to keep investing in life."],"ru":["Я понимаю, что сейчас имеет для меня смысл.","Мои повседневные действия связаны с тем, что мне важно.","Я могу назвать, чего хочу больше в своей жизни.","Я различаю то, что важно мне, и то, чего от меня просто ждут.","У меня есть хотя бы одно направление, в котором я хочу двигаться.","Даже в трудностях я вижу хотя бы некоторую причину продолжать вкладываться в жизнь."],"ids":{"en":"8634ee78-fb65-5651-a742-3cffc0c1fcf6","ru":"2e6332ec-a9a7-55d1-8e6d-8809251a9c81"},"hashes":{"en":"sha256:cc0ab07c0cc6317501c9710ca0cf3bb45a295ae24ef2794e130e7f66a234d954","ru":"sha256:d95d063aaef61df53e2da7f5ed1a07897896f26fd70039d8280c598fa1623d0f"},"negative":false},{"key":"hh-motivation-spark","titles":{"en":"Motivation Spark","ru":"Искра мотивации"},"axis":"resources","topics":["motivation","energy","function"],"categoryAffinities":["work-money","energy","other"],"testLength":"short","en":["There is something I genuinely want to move toward.","I can feel at least a small spark of interest in a task or project.","I can connect effort with a reason that matters to me.","Small progress gives me some energy.","I can distinguish lack of motivation from simple exhaustion.","I know one next action that could create momentum."],"ru":["Есть что-то, к чему я действительно хочу двигаться.","Я чувствую хотя бы небольшой интерес к задаче или проекту.","Я могу связать усилие с причиной, которая для меня важна.","Небольшой прогресс даёт мне немного энергии.","Я могу отличить отсутствие мотивации от обычной усталости.","Я знаю одно следующее действие, которое может создать движение."],"ids":{"en":"20dd445b-2c3a-5375-944b-f0cffda1898e","ru":"57bc2c90-0672-5ea3-b825-bf583290f94a"},"hashes":{"en":"sha256:157b8891fa54d5cebd652d397e3f21329d19389537c63d3725234d950e7cee88","ru":"sha256:806aec8de59e7133046496da9c756a8cb122cfc8039c7c05b2572139ff2215e6"},"negative":false}]$configs$::jsonb)
  loop
    foreach locale in array array['en','ru']
    loop
      select jsonb_agg(
        jsonb_build_object(
          'id',(cfg->>'key')||'.'||lpad(ord::text,2,'0'),
          'text',txt,
          'required',true,
          'direction',case when (cfg->>'negative')::boolean then 'lower-reported-difficulty' else 'higher-reported-resource' end
        ) order by ord
      ) into questions
      from jsonb_array_elements_text(cfg->locale) with ordinality as q(txt,ord);

      select jsonb_agg((cfg->>'key')||'.'||lpad(ord::text,2,'0') order by ord)
      into item_ids
      from generate_series(1,jsonb_array_length(cfg->locale)) as ord;

      dimension_class := case cfg->>'axis' when 'function' then 'function' when 'state' then 'state' else 'resources' end;
      direction := case when (cfg->>'negative')::boolean then 'lower-reported-difficulty' else 'higher-reported-resource' end;
      timeframe := case when cfg->>'key' in ('hh-sleep-reset','hh-evening-landing','hh-workload-weather','hh-money-pressure','hh-daily-rhythm') then 'past-7-days' else 'right-now' end;
      test_id := (cfg->'ids'->>locale)::uuid;
      v_content_hash := cfg->'hashes'->>locale;

      definition := jsonb_build_object(
        'id',test_id::text,'key',cfg->>'key','version','v1','instrumentLocale',locale,
        'translationVersion','hh-'||locale||'-v1','timeframe',timeframe,
        'scoringKey','configured','scoringVersion','v1','resultVersion','v1',
        'title',cfg->'titles'->>locale,
        'source',jsonb_build_object('title','Holistic House — '||(cfg->'titles'->>'en'),'status','original-playful-non-diagnostic-reflection','reviewedAt','2026-10-06'),
        'answerScale',jsonb_build_object('min',0,'max',4),
        'responseAnchors',case when locale='ru'
          then '["Совсем нет","Немного","Отчасти","В значительной степени","Очень сильно"]'::jsonb
          else '["Not at all","A little","Somewhat","Quite a lot","Very much"]'::jsonb end,
        'scoring',jsonb_build_object('dimensions',jsonb_build_array(jsonb_build_object(
          'key',dimension_class||'.'||replace(regexp_replace(cfg->>'key','^hh-',''),'-','_')||'.overall',
          'method','mean','items',item_ids,'min',0,'max',4,'dimensionClass',dimension_class,
          'sourceConstruct',cfg->'titles'->>locale,'direction',direction
        ))),
        'questions',questions,'optionalContext','[]'::jsonb,
        'suggestedRepeatDays',case when cfg->>'testLength'='short' then 7 else 14 end,
        'contentHash',v_content_hash
      );

      if exists(select 1 from app.assessment_versions where id=test_id and app.assessment_versions.content_hash<>v_content_hash) then
        raise exception 'Published engaging assessment definition % differs from reviewed definition', test_id;
      end if;

      insert into app.assessment_versions(
        id,definition_key,definition_version,instrument_locale,translation_version,
        definition,questions,answer_schema,scoring_key,scoring_version,result_schema,
        timeframe,source_metadata,content_hash
      ) values (
        test_id,definition->>'key','v1',locale,definition->>'translationVersion',
        definition,questions,jsonb_build_object('type','integer','minimum',0,'maximum',4),
        'configured','v1',jsonb_build_object('version','v1'),timeframe,definition->'source',v_content_hash
      ) on conflict(id) do nothing;
    end loop;
  end loop;
end $$;
commit;
